const stopwords = new Set(['yang','dan','di','ke','dari','ini','itu','untuk','pada','dengan','atau','jadi','bisa','akan','ada','dalam','saat','para','oleh','apakah','kenapa','mengapa','bagaimana','masih','makin','terus','lebih','kian','buka','membuka','peluang','alasan','alasannya']);
const negative = ['australia','portugal','vietnam','amerika','inggris','jepang','china','10 negara','zuckerberg','bezos','musk','artis','seleb','suami','istri','cerai','pesawat','penerbangan','kendaraan listrik','mobil listrik','kripto'];
const positive = {'kpr':4,'suku bunga':4,'cicilan':3,'subsidi':3,'rumah bekas':3,'rumah lelang':3,'gaji':3,'harga rumah':3,'pasar properti':3,'bphtb':3,'ppn dtp':3,'dp':2,'bank':2,'kredit':2,'sewa':2,'ngontrak':2,'pekerja muda':2,'milenial':2,'gen z':2,'jakarta':2,'bekasi':2,'bogor':2,'depok':2,'tangerang':2,'ri':2};
const trusted = new Set(['cnbc indonesia','kompas.com','bisnis.com','kontan.co.id','investor.id','detikcom','detikfinance','kumparan','tempo.co','liputan6.com','antaranews.com']);
const hasWord = (text, kw) => new RegExp(`\\b${kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i').test(text);

function tokenize(title) {
  const matches = title.toLowerCase().match(/\d+(?:[.,]\d+)?|[a-z]{3,}/g) || [];
  return new Set(matches.filter(t => !stopwords.has(t)));
}

function jaccard(a, b) {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / (a.size + b.size - inter);
}

const scored = [];
for (const item of $input.all()) {
  const rawTitle = (item.json.title || '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&#39;|&apos;/g, "'").trim();
  const parts = rawTitle.split(' - ');
  const source = parts.length > 1 ? parts[parts.length - 1].trim() : 'Google News';
  const title = parts.length > 1 ? parts.slice(0, -1).join(' - ').trim() : rawTitle;
  const hay = `${title} ${source}`.toLowerCase();
  if (negative.some(neg => hasWord(hay, neg))) continue;
  let score = 0;
  for (const [kw, w] of Object.entries(positive)) {
    if (hasWord(hay, kw)) score += w;
  }
  if (trusted.has(source.toLowerCase())) score += 4;
  if (score > 0 && title) {
    scored.push({
      title,
      source,
      published_at: item.json.pubDate || item.json.isoDate || '',
      url: item.json.link || '',
      relevance_score: score,
      _tokens: tokenize(title)
    });
  }
}

scored.sort((a, b) => b.relevance_score - a.relevance_score);
const selected = [];
const outletCounts = {};
for (const cand of scored) {
  const key = cand.source.toLowerCase();
  if ((outletCounts[key] || 0) >= 2) continue;
  const isDup = selected.some(s => jaccard(cand._tokens, s._tokens) >= 0.32);
  if (!isDup) {
    selected.push(cand);
    outletCounts[key] = (outletCounts[key] || 0) + 1;
  }
  if (selected.length >= 3) break;
}

return selected.map(({ _tokens, ...rest }, i) => ({ json: { slot: i + 1, ...rest } }));

