const ranked = $('Deduplicate & Rank Top 3 (Code)').all();
return $input.all().map((item, idx) => {
  let text = (item.json.text || item.json.response || '').replace(/\*\*/g, '').replace(/__/g, '');
  text = text.replace(/\u202f/g, '').replace(/\u00a0/g, ' ').replace(/\u2011/g, '-');
  text = text.replace(/^#{1,6}\s+/gm, '').replace(/^\s*[\*\-]\s+/gm, '• ');
  text = text.replace(/^(\d+\.)([A-Za-z])/gm, '$1 $2').replace(/([a-z])(20\d{2})\b/g, '$1 $2');
  text = text.replace(/\u2014/g, ', ').replace(/\u2013/g, '-').replace(/ -- /g, ', ');
  text = text.replace(/,[ \t]*,/g, ',').replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const hookWords = lines.length ? lines[0].split(/\s+/).length : 0;
  const hashtags = text.match(/#[A-Za-z0-9_]+/g) || [];
  const bodyWithoutTags = text.replace(/#[A-Za-z0-9_]+/g, '').trim();
  const wordCount = bodyWithoutTags ? bodyWithoutTags.split(/\s+/).length : 0;
  const hasBrand = bodyWithoutTags.toLowerCase().includes('rumah123');
  const usesFormalAnda = /\banda\b/i.test(bodyWithoutTags);

  const issues = [];
  if (hookWords > 16) issues.push(`hook_too_long (${hookWords})`);
  if (wordCount < 95 || wordCount > 250) issues.push(`word_count_out_of_range (${wordCount})`);
  if (hashtags.length < 3 || hashtags.length > 6) issues.push(`hashtag_count_out_of_range (${hashtags.length})`);
  if (!hasBrand) issues.push('missing_rumah123_mention');
  if (usesFormalAnda) issues.push('formal_pronoun_anda');

  const passed = issues.length === 0;
  const src = ranked[idx] ? ranked[idx].json : {};
  return {
    json: {
      slot: idx + 1,
      source_article: src,
      status: passed ? 'READY_FOR_REVIEW' : 'NEEDS_REVISION',
      quality_gate: {
        passed,
        metrics: {
          hook_words: hookWords,
          word_count: wordCount,
          hashtag_count: hashtags.length,
          has_rumah123_mention: hasBrand,
          uses_kamu_voice: !usesFormalAnda
        },
        issues
      },
      instagram_caption: text
    }
  };
});
